-- Catálogo amplo para TESTES de simulação visual.
-- Execute no SQL Editor após a migration principal.
-- Os itens não autorizam execução clínica. Confirme habilitação profissional,
-- registro e instruções de uso na Anvisa antes de qualquer uso real.

begin;

on conflict (name) do update set description=excluded.description, regions=excluded.regions,
  questions=excluded.questions, requires_product=excluded.requires_product, active=true;

-- Itens genéricos de teste: substitua por marcas e apresentações reais.
with product_seed(procedure_name, name, brand, unit) as (
  values
    ('Toxina botulínica', 'Toxina botulínica tipo A — TESTE', 'Cadastrar fabricante real', 'unidades'),
    ('Preenchimento com ácido hialurônico', 'Ácido hialurônico — TESTE', 'Cadastrar fabricante real', 'mL'),
    ('Bioestimulação de colágeno', 'Hidroxiapatita de cálcio — TESTE', 'Cadastrar fabricante real', 'mL'),
    ('Bioestimulação de colágeno', 'Ácido poli-L-láctico (PLLA) — TESTE', 'Cadastrar fabricante real', 'frasco'),
    ('Skinbooster / hidratação injetável', 'Ácido hialurônico para hidratação — TESTE', 'Cadastrar fabricante real', 'mL'),
    ('Fios de sustentação', 'Fio absorvível — TESTE', 'Cadastrar fabricante real', 'unidade'),
    ('Peeling químico', 'Agente de peeling — TESTE', 'Cadastrar produto real', 'aplicação')
)
select p.id, s.name, s.brand, s.unit, true from product_seed s
join public.aesthetic_procedures p on p.name=s.procedure_name
on conflict (procedure_id, name, brand) do update set unit=excluded.unit, active=true;

commit;
